"use client";
import * as React from "react";
import { RichValue } from "@/registry/p1/internal/rich";
import "./tabs.css";

export interface TabItem {
  label: string;
  body: string;
}

export interface TabsProps {
  heading: string;
  align: "left" | "center";
  tabs: TabItem[];
}

export function TabsRender({ heading, align, tabs }: TabsProps) {
  const list = tabs || [];
  const [active, setActive] = React.useState(list[0]?.label ?? "");
  // Stay on a valid tab after the author reorders or deletes tabs.
  const activeLabel = list.some((t) => t.label === active) ? active : (list[0]?.label ?? "");
  const i = list.findIndex((t) => t.label === activeLabel);
  return (
    <div className="p1-tabs p1-block" data-align={align}>
      {heading && <h2 className="p1-tabs__heading">{heading}</h2>}
      <div className="p1-tabs__bar" role="tablist">
        {list.map((tb, ti) => {
          const on = tb.label === activeLabel;
          return (
            <button
              key={tb.label || ti}
              type="button"
              role="tab"
              aria-selected={on}
              data-active={on ? "true" : undefined}
              onClick={() => setActive(tb.label)}
              className="p1-tabs__tab"
            >
              {tb.label || `Tab ${ti + 1}`}
            </button>
          );
        })}
      </div>
      <div className="p1-tabs__panel" role="tabpanel">
        <RichValue value={(list[i] ?? ({} as TabItem)).body ?? ""} />
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { TabsRender, type TabsProps, type TabItem } from "./tabs";
export type { TabsProps, TabItem };

export const TabsBlock: ComponentConfig<TabsProps> = {
  fields: {
    heading: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "A section heading of 2–6 words. Plain text, sentence case, no trailing punctuation." },
    },
    align: {
      type: "radio" as const,
      options: [
        { label: "Left", value: "left" },
        { label: "Center", value: "center" },
      ],
    },
    tabs: {
      type: "array" as const,
      arrayFields: {
        label: { type: "text" as const, contentEditable: true, visible: false },
        body: { type: "richtext" as const, contentEditable: true },
      },
      defaultItemProps: { label: "Tab", body: "<p>Tab content.</p>" },
      getItemSummary: (item: TabItem) => item.label || "Tab",
    },
  },
  defaultProps: {
    heading: "Everything in one workflow",
    align: "left",
    tabs: [
      {
        label: "Develop",
        body: "<p>Branch every change into its own <mark>Multidev</mark> environment.</p><ul><li>No more stepping on each other</li><li>Real URLs to share for review</li><li>Merge when it's ready</li></ul>",
      },
      {
        label: "Test",
        body: "<p>Push to Test with one click and run against <mark>production-like data</mark>.</p><ul><li>Automated visual checks</li><li>Stakeholder sign-off</li><li>Nothing surprises you on Live</li></ul>",
      },
      {
        label: "Launch",
        body: "<p>Deploy to Live in seconds — and roll back just as fast if you need to.</p><blockquote>Confidence to publish on a Friday afternoon.</blockquote>",
      },
    ],
  },
  render: TabsRender,
};

export const meta = defineMeta({
  title: 'Tabs',
  description: 'Tabbed content switcher with a heading and per-tab rich-text body; use to organize related content into switchable panels.',
  categories: ["layout"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-rich"],
});

.p1-tabs {
  margin-inline: auto;
  max-inline-size: var(--p1-container-default);
}

.p1-tabs__heading {
  font-family: var(--p1-font-heading);
  font-size: var(--p1-text-2xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
  line-height: var(--p1-leading-tight);
  margin-block-end: var(--p1-space-lg);
}
@media (width >= 48rem) {
  .p1-tabs__heading { font-size: var(--p1-text-3xl); }
}
.p1-tabs[data-align="center"] .p1-tabs__heading { text-align: center; }

.p1-tabs__bar {
  border-block-end: 1px solid var(--p1-border);
  display: flex;
  flex-wrap: wrap;
  gap: var(--p1-space-xs);
  margin-block-end: var(--p1-space-lg);
}
.p1-tabs[data-align="center"] .p1-tabs__bar { justify-content: center; }

.p1-tabs__tab {
  background: none;
  border: 0;
  border-block-end: 2px solid transparent;
  color: var(--p1-fg-muted);
  cursor: pointer;
  font-weight: var(--p1-weight-bold);
  margin-block-end: -1px;
  padding-block: var(--p1-space-sm);
  padding-inline: var(--p1-space-md);
}
@media (prefers-reduced-motion: no-preference) {
  .p1-tabs__tab { transition: color 150ms ease, border-color 150ms ease; }
}
.p1-tabs__tab:hover { color: var(--p1-fg-default); }
.p1-tabs__tab[data-active="true"] {
  border-block-end-color: var(--p1-accent);
  color: var(--p1-fg-default);
}

